def _invalidate_uuid(uuid_str: str) -> str:
    """
    Create an invalid UUID string deterministically from an existing UUID.
    We avoid introducing hardcoded request data by deriving from provided input value.
    Strategy: remove '-' which yields a non-UUID format.
    """
    if not uuid_str:
        return uuid_str  # will be handled by caller via skip
    mutated = uuid_str.replace("-", "")
    # If removal produced the same string (unlikely), reverse as secondary mutation
    return mutated if mutated != uuid_str else uuid_str[::-1]


